const claudeResponse = $input.first().json.content[0].text;
const cleaned = claudeResponse.replace(/```json|```/g, '').trim();
const claudeOutput = JSON.parse(cleaned);

const extraction = claudeOutput.extractions[0];

const webhook = $('Webhook').first().json;
const buildContext = $('3c_Build - Current Date').first().json;

return [{
  json: {
    ...extraction,
    po_line_key: webhook.body.call.metadata.po_line_key,
    po_number: webhook.body.call.metadata.po_number,
    follow_up_stage: webhook.body.call.metadata.follow_up_stage,
    call_number: webhook.body.call.metadata.call_number,
    deliver_by_date: buildContext.deliver_by_date,
    ship_by_date: buildContext.ship_by_date,
    email_found: extraction.supplier_responded   // ← ADD THIS LINE
  }
}];

const classification = $('6_Call - Classify – Delivery Status v1').first().json;
const webhook = $('Webhook').first().json;
const stage = webhook.body.call.metadata.follow_up_stage;
const prefix = stage.toLowerCase().replace('.', '_') + '_';
const callEndTimestamp = webhook.body.call.end_timestamp 
  ? new Date(webhook.body.call.end_timestamp).toISOString() 
  : new Date().toISOString();

return [{
  json: {
    po_line_key: webhook.body.call.metadata.po_line_key,
    follow_up_status: 'Call1_Sent',
    last_action_timestamp: new Date().toISOString(),
    // Call execution metadata
    [`${prefix}reminder_call1_sent`]: 'Yes',
    [`${prefix}reminder_call1_timestamp`]: callEndTimestamp,
    [`${prefix}reminder_call1_answered`]: 'Yes',
    [`${prefix}reminder_call1_call_outcome`]: 'human_conversation',
    // Call-specific reply capture
    [`${prefix}reminder_call1_delivery_status_classification`]: classification.classification || '',
    [`${prefix}reminder_call1_delivery_status_text`]: classification.classification_detail || '',
    [`${prefix}reminder_call1_supplier_raw_statement`]: classification.raw_supplier_statement || '',
    // Stage-level reply schema (mirror)
    [`${prefix}supplier_reply_status`]: 'Received',
    [`${prefix}reply_timestamp`]: callEndTimestamp,
    [`${prefix}delivery_status_classification`]: classification.classification || '',
    [`${prefix}delivery_status_text`]: classification.classification_detail || '',
    [`${prefix}supplier_raw_statement`]: classification.raw_supplier_statement || '',
    [`${prefix}supplier_reply_message_id`]: 'N/A',
    [`${prefix}mode_of_reply_received`]: 'call',
    [`${prefix}supplier_reply_confidence`]: classification.confidence || '',
    // Human review flag
    needs_human_review: classification.needs_human_review ? 'Yes' : '',
    human_review_status: classification.needs_human_review ? 'Pending' : ''
  }
}];

