const webhook = $('Webhook').first().json;
const stage = webhook.body.call.metadata.follow_up_stage;
const prefix = stage.toLowerCase().replace('.', '_') + '_';
const callNumber = webhook.body.call.metadata.call_number; 
// expected values: "make_call1" | "make_call2" | "make_call3"
const callIndex = callNumber.replace('make_call', '');
const callOutcome = webhook.body.call.call_analysis?.custom_analysis_data?.call_outcome || '';
const callEndTimestamp = webhook.body.call.end_timestamp 
  ? new Date(webhook.body.call.end_timestamp).toISOString() 
  : new Date().toISOString();

return [{
  json: {
    po_line_key: webhook.body.call.metadata.po_line_key,
    follow_up_status: `Call${callIndex}_Sent`,
    last_action_timestamp: new Date().toISOString(),
    [`${prefix}reminder_call${callIndex}_sent`]: 'Yes',
    [`${prefix}reminder_call${callIndex}_timestamp`]: callEndTimestamp,
    [`${prefix}reminder_call${callIndex}_answered`]: 'No',
    [`${prefix}reminder_call${callIndex}_call_outcome`]: callOutcome
  }
}];

const webhook = $('Webhook').first().json;
const commsLog = $('3a_Read - Communication logs').first().json;
const poDetails = $('3b_Read - PO Details').first().json;

const timezone = webhook.body.call.metadata.client_timezone;
const today = new Date().toLocaleDateString('en-CA', { timeZone: timezone });

const call = webhook.body.call;

return [{
  json: {
    ...commsLog,
    current_date: today,
    client_timezone: timezone,

    // PO identity
    po_line_key: call.metadata.po_line_key,
    po_number: call.metadata.po_number,
    follow_up_stage: call.metadata.follow_up_stage,
    call_number: call.metadata.call_number,

    // PO details from sheet
    material_name: poDetails.material_name,
    material_code: poDetails.material_code,
    supplier_name: poDetails.supplier_name,
    deliver_by_date: poDetails.deliver_by_date_delivery_1,
    ship_by_date: poDetails.ship_by_date_delivery_1,
    issue_date: poDetails.issue_date,
    quantity: poDetails.quantity,
    unit: poDetails.unit,

    // Call content
    call_transcript: call.transcript,
    call_summary: call.call_analysis?.call_summary || ''
  }
}];
